package calc

// IsEven returns true if n is even, false otherwise.
func IsEven(n int) bool {
	return n%2 == 0
}

package calc

import "testing"

func TestIsEven(t *testing.T) {
	tests := []struct {
		n    int
		want bool
	}{
		{0, true},
		{1, false},
		{2, true},
		{-1, false},
		{-2, true},
		{100, true},
		{99, false},
	}
	for _, tt := range tests {
		got := IsEven(tt.n)
		if got != tt.want {
			t.Errorf("IsEven(%d) = %v; want %v", tt.n, got, tt.want)
		}
	}
}

